-- Scheduling (Stream 4): InstructorCourse (M:N), InstructorAvailability, ClassSession and structured
-- student preferences on Enrollment. STAGED + ADDITIVE: nothing is dropped or rewritten;
-- Course.instructorId keeps working (it is the public /tutors "primary instructor").
--
-- Part 1 is the DDL (generated by `prisma migrate diff`). Part 2 is raw SQL Prisma cannot express:
-- the btree_gist EXCLUSION constraints that make double-booking impossible at the database level,
-- CHECKs, a partial unique index and the InstructorCourse backfill.
--
-- DEPLOY NOTE: snapshot production first and use the DIRECT (non-Accelerate) DB URL. Part 2 runs
-- `CREATE EXTENSION btree_gist`: on PG13+ it is a "trusted" extension (database owner may create it);
-- on a managed host confirm it is available BEFORE deploying, or this migration fails (and wedges later
-- deploys with P3009 until resolved).

-- ============================== Part 1: DDL ==============================

-- AlterTable
ALTER TABLE "enrollments" ADD COLUMN     "preferredClassesPerWeek" INTEGER,
ADD COLUMN     "preferredFromTime" TEXT,
ADD COLUMN     "preferredTimeBands" TEXT[] DEFAULT ARRAY[]::TEXT[],
ADD COLUMN     "preferredToTime" TEXT;

-- CreateTable
CREATE TABLE "instructor_courses" (
    "instructorId" TEXT NOT NULL,
    "courseId" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "instructor_courses_pkey" PRIMARY KEY ("instructorId","courseId")
);

-- CreateTable
CREATE TABLE "instructor_availability" (
    "id" TEXT NOT NULL,
    "instructorId" TEXT NOT NULL,
    "weekday" INTEGER NOT NULL,
    "startMinute" INTEGER NOT NULL,
    "endMinute" INTEGER NOT NULL,
    "locationId" TEXT NOT NULL,
    "mode" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "instructor_availability_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "class_sessions" (
    "id" TEXT NOT NULL,
    "enrollmentId" TEXT NOT NULL,
    "studentId" TEXT NOT NULL,
    "instructorId" TEXT NOT NULL,
    "locationId" TEXT,
    "mode" TEXT NOT NULL,
    "startsAt" TIMESTAMPTZ(3) NOT NULL,
    "durationMins" INTEGER NOT NULL,
    "endsAt" TIMESTAMPTZ(3) NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'scheduled',
    "sequence" INTEGER NOT NULL,
    "rescheduledFromId" TEXT,
    "notes" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "class_sessions_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "instructor_courses_courseId_idx" ON "instructor_courses"("courseId");

-- CreateIndex
CREATE INDEX "instructor_availability_instructorId_weekday_idx" ON "instructor_availability"("instructorId", "weekday");

-- CreateIndex
CREATE INDEX "instructor_availability_locationId_idx" ON "instructor_availability"("locationId");

-- CreateIndex
CREATE INDEX "class_sessions_instructorId_startsAt_idx" ON "class_sessions"("instructorId", "startsAt");

-- CreateIndex
CREATE INDEX "class_sessions_enrollmentId_sequence_idx" ON "class_sessions"("enrollmentId", "sequence");

-- CreateIndex
CREATE INDEX "class_sessions_studentId_startsAt_idx" ON "class_sessions"("studentId", "startsAt");

-- CreateIndex
CREATE UNIQUE INDEX "enrollments_id_studentId_key" ON "enrollments"("id", "studentId");

-- AddForeignKey
ALTER TABLE "instructor_courses" ADD CONSTRAINT "instructor_courses_instructorId_fkey" FOREIGN KEY ("instructorId") REFERENCES "instructors"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "instructor_courses" ADD CONSTRAINT "instructor_courses_courseId_fkey" FOREIGN KEY ("courseId") REFERENCES "courses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "instructor_availability" ADD CONSTRAINT "instructor_availability_instructorId_fkey" FOREIGN KEY ("instructorId") REFERENCES "instructors"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "instructor_availability" ADD CONSTRAINT "instructor_availability_locationId_fkey" FOREIGN KEY ("locationId") REFERENCES "locations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "class_sessions" ADD CONSTRAINT "class_sessions_enrollmentId_studentId_fkey" FOREIGN KEY ("enrollmentId", "studentId") REFERENCES "enrollments"("id", "studentId") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "class_sessions" ADD CONSTRAINT "class_sessions_instructorId_fkey" FOREIGN KEY ("instructorId") REFERENCES "instructors"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "class_sessions" ADD CONSTRAINT "class_sessions_locationId_fkey" FOREIGN KEY ("locationId") REFERENCES "locations"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "class_sessions" ADD CONSTRAINT "class_sessions_rescheduledFromId_fkey" FOREIGN KEY ("rescheduledFromId") REFERENCES "class_sessions"("id") ON DELETE SET NULL ON UPDATE CASCADE;


-- ============================ Part 2: raw SQL ============================

CREATE EXTENSION IF NOT EXISTS btree_gist;

-- Backfill: every course's legacy primary instructor teaches it.
INSERT INTO "instructor_courses" ("instructorId", "courseId")
SELECT "instructorId", "id" FROM "courses" WHERE "instructorId" IS NOT NULL
ON CONFLICT DO NOTHING;

-- ---- instructor_availability: sane windows, and one instructor cannot be in two places at once
ALTER TABLE "instructor_availability"
  ADD CONSTRAINT "instructor_availability_weekday_chk" CHECK ("weekday" BETWEEN 1 AND 7),
  ADD CONSTRAINT "instructor_availability_minutes_chk" CHECK ("startMinute" >= 0 AND "endMinute" <= 1440 AND "startMinute" < "endMinute"),
  ADD CONSTRAINT "instructor_availability_mode_chk" CHECK ("mode" IN ('CENTRE', 'HOME', 'ONLINE')),
  ADD CONSTRAINT "instructor_availability_no_overlap"
    EXCLUDE USING gist ("instructorId" WITH =, "weekday" WITH =, int4range("startMinute", "endMinute") WITH &&);

-- ---- class_sessions: vocabularies, the endsAt pin, sequence
-- endsAt is stored (timestamptz + interval is not IMMUTABLE, so it cannot be generated or indexed);
-- this CHECK keeps it equal to startsAt + duration so the exclusion ranges below cannot lie.
ALTER TABLE "class_sessions"
  ADD CONSTRAINT "class_sessions_duration_chk" CHECK ("durationMins" IN (45, 60)),
  ADD CONSTRAINT "class_sessions_status_chk" CHECK ("status" IN ('scheduled', 'held', 'missed', 'rescheduled', 'cancelled')),
  ADD CONSTRAINT "class_sessions_mode_chk" CHECK ("mode" IN ('CENTRE', 'HOME', 'ONLINE')),
  ADD CONSTRAINT "class_sessions_ends_chk" CHECK ("endsAt" = "startsAt" + "durationMins" * interval '1 minute'),
  ADD CONSTRAINT "class_sessions_sequence_chk" CHECK ("sequence" >= 1);

-- Class slot n of an enrollment is occupied by at most one scheduled/held/missed session.
-- 'rescheduled' and 'cancelled' free the slot.
CREATE UNIQUE INDEX "class_sessions_slot_unique"
  ON "class_sessions" ("enrollmentId", "sequence")
  WHERE "status" IN ('scheduled', 'held', 'missed');

-- THE conflict guarantee. Active = scheduled | held. Half-open ranges: a class ending 10:00 and one
-- starting 10:00 do not conflict. Two concurrent inserts for the same slot: the second blocks until the
-- first commits, then fails with SQLSTATE 23P01 (mapped to a friendly error in lib/scheduling/conflict-error.ts).
ALTER TABLE "class_sessions"
  ADD CONSTRAINT "class_sessions_instructor_no_overlap"
    EXCLUDE USING gist ("instructorId" WITH =, tstzrange("startsAt", "endsAt", '[)') WITH &&)
    WHERE ("status" IN ('scheduled', 'held')),
  ADD CONSTRAINT "class_sessions_student_no_overlap"
    EXCLUDE USING gist ("studentId" WITH =, tstzrange("startsAt", "endsAt", '[)') WITH &&)
    WHERE ("status" IN ('scheduled', 'held'));
